977	// TestRejectedReplacementKeepsAcceptedStateAndRotation is the regression guard
978	// for replacement requests against an existing service whose rotation is
979	// already in use: a rejected register must not partially replace instances,
980	// reset accepted health, consume a revision or move the selection position, and
981	// later selects in the same batch must keep using the previously accepted
982	// state. Two rejection conditions are exercised:
983	//
984	//   - a list with a valid prefix that changes an existing address followed by an
985	//     invalid instance address is invalid as a whole (field validation precedes
986	//     the revision check, so a simultaneously wrong expectedRevision still
987	//     reports invalid), and the valid prefix must not take effect;
988	//   - a fully valid list with a mismatched expectedRevision is a conflict
989	//     naming both revisions; no part of the replacement is applied.
990	func TestRejectedReplacementKeepsAcceptedStateAndRotation(t *testing.T) {
991		input := `{"requests":[
992			{"type":"register","service":"svc","expectedRevision":0,"instances":[{"id":"i1","address":"h1:8080"},{"id":"i2","address":"h2:8080"}]},
993			{"type":"health","service":"svc","instanceId":"i1","expectedRevision":1,"sequence":11,"healthy":true},
994			{"type":"health","service":"svc","instanceId":"i2","expectedRevision":1,"sequence":22,"healthy":true},
995			{"type":"select","service":"svc","expectedRevision":1},
996			{"type":"register","service":"svc","expectedRevision":9,"instances":[{"id":"i1","address":"h9:8080"},{"id":"i2","address":"bad-address"}]},
997			{"type":"select","service":"svc","expectedRevision":1},
998			{"type":"register","service":"svc","expectedRevision":5,"instances":[{"id":"i1","address":"hx:8080"},{"id":"i2","address":"h2:8080"}]},
999			{"type":"select","service":"svc","expectedRevision":1}
1000		]}`
1001		out, code := runRegisterWith(t, input)
1002		if code != 1 {
1003			t.Fatalf("batch contains failures, exit code: %d, output: %s", code, out)
1004		}
1005		var got registerOutput
1006		if err := json.Unmarshal([]byte(out), &got); err != nil {
1007			t.Fatalf("output is not JSON: %v\n%s", err, out)
1008		}
1009		// The failed items keep their slots, in input order, with the later
1010		// successful selects still present; a later success does not cancel the
1011		// earlier failures.
1012		if len(got.Results) != 8 {
1013			t.Fatalf("results: %+v", got.Results)
1014		}
1015		// 0: accepted registration at revision 1.
1016		if r := got.Results[0]; !r.OK || !r.Changed || r.Revision != 1 {
1017			t.Fatalf("result 0: %+v", r)
1018		}
1019		// 1-2: both offline health observations accepted without a revision bump.
1020		if r := got.Results[1]; !r.OK || !r.Changed || r.Revision != 1 || r.Sequence != 11 {
1021			t.Fatalf("result 1: %+v", r)
1022		}
1023		if r := got.Results[2]; !r.OK || !r.Changed || r.Revision != 1 || r.Sequence != 22 {
1024			t.Fatalf("result 2: %+v", r)
1025		}
1026		// 3: first selection takes the smallest healthy id, cursor rests on i1.
1027		if r := got.Results[3]; !r.OK || r.InstanceID != "i1" || r.Address != "h1:8080" || r.Sequence != 11 || r.Revision != 1 {
1028			t.Fatalf("result 3: %+v", r)
1029		}
1030		// 4: the later instance address is invalid. The whole item is invalid even
1031		// though expectedRevision 9 is also wrong, because field validation precedes
1032		// the revision check; the reason names the bad address and no revision
1033		// comparison is reported. The valid prefix (i1's new address) must not be
1034		// applied either.
1035		if r := got.Results[4]; r.OK || r.Error != "invalid" || r.Revision != 1 ||
1036			r.ExpectedRevision != 0 || r.ActualRevision != 0 ||
1037			r.InstanceID != "" || r.Address != "" {
1038			t.Fatalf("result 4 invalid rejection: %+v", r)
1039		}
1040		if !strings.Contains(got.Results[4].Reason, `instance address "bad-address" is not a host:port address`) {
1041			t.Fatalf("result 4 reason should name the bad address, got %q", got.Results[4].Reason)
1042		}
1043		// 5: selection after the invalid replacement continues just after i1 and
1044		// lands on i2 using its ORIGINAL address and accepted sequence, proving the
1045		// rejected list neither reset i2 to unknown nor advanced the cursor.
1046		if r := got.Results[5]; !r.OK || r.InstanceID != "i2" || r.Address != "h2:8080" || r.Sequence != 22 || r.Revision != 1 {
1047			t.Fatalf("result 5: %+v", r)
1048		}
1049		// 6: the list itself is valid, only expectedRevision mismatches: conflict
1050		// states the expected and current revisions; no new address is accepted.
1051		if r := got.Results[6]; r.OK || r.Error != "conflict" ||
1052			r.Reason != `service "svc" is at revision 1, not 5` ||
1053			r.Revision != 1 || r.ExpectedRevision != 5 || r.ActualRevision != 1 {
1054			t.Fatalf("result 6 conflict: %+v", r)
1055		}
1056		// 7: past the end the rotation wraps to the smallest healthy id, returning
1057		// i1's ORIGINAL address h1:8080 and sequence 11 — not the rejected hx:8080,
1058		// and not i2 again, which would mean the failed conflict reset the cursor.
1059		if r := got.Results[7]; !r.OK || r.InstanceID != "i1" || r.Address != "h1:8080" || r.Sequence != 11 || r.Revision != 1 {
1060			t.Fatalf("result 7: %+v", r)
1061		}
1062	
1063		// The final service list reflects only accepted registrations and
1064		// observations: revision unchanged at 1, both original addresses, both
1065		// instances still healthy with their accepted sequences, and neither
1066		// rejected address present anywhere.
1067		if len(got.Services) != 1 {
1068			t.Fatalf("services: %+v", got.Services)
1069		}
1070		svc := got.Services[0]
1071		if svc.Service != "svc" || svc.Revision != 1 {
1072			t.Fatalf("service view: %+v", svc)
1073		}
1074		if len(svc.Instances) != 2 {
1075			t.Fatalf("instances: %+v", svc.Instances)
1076		}
1077		wantInsts := []registerInstance{
1078			{ID: "i1", Address: "h1:8080", Health: "healthy", Sequence: 11},
1079			{ID: "i2", Address: "h2:8080", Health: "healthy", Sequence: 22},
1080		}
1081		for i, want := range wantInsts {
1082			if svc.Instances[i] != want {
1083				t.Fatalf("instance %d: got %+v want %+v", i, svc.Instances[i], want)
1084			}
1085		}
